enum class Transport { http, https, tcp, wss };

// Target deployment environment.
enum class Deployment { public_network, local_development };

// A parsed endpoint. host is a DNS name, IPv4 address, or an unbracketed
// IPv6 literal; this header performs no DNS/IP syntax validation.
struct Endpoint {
    Transport transport;
    std::string host;
    std::uint16_t port;
};

// The two endpoints a session should use.
struct ConnectionPlan {
    Endpoint api;
    Endpoint game;
};

inline std::optional<ConnectionPlan> plan_connections(Deployment mode,
                                                      const Endpoint& api,
                                                      const Endpoint& game) {
    // Reject an out-of-range Deployment value.
    if (mode != Deployment::public_network && mode != Deployment::local_development) {
        return std::nullopt;
    }

    // API must be http or https; game must be tcp or wss.
    const bool apiSecure = api.transport == Transport::https;
    const bool apiInsecure = api.transport == Transport::http;
    const bool gameSecure = game.transport == Transport::wss;
    const bool gameInsecure = game.transport == Transport::tcp;
    if (!apiSecure && !apiInsecure) {
        return std::nullopt;
    }
    if (!gameSecure && !gameInsecure) {
        return std::nullopt;
    }

    // Both parsed hosts must pass the byte filter and both ports must be non-zero.
    if (!has_safe_host_text(api.host) || !has_safe_host_text(game.host)) {
        return std::nullopt;
    }
    if (api.port == 0 || game.port == 0) {
        return std::nullopt;
    }

    if (mode == Deployment::public_network) {
        // Public network forbids every insecure transport.
        if (!apiSecure || !gameSecure) {
            return std::nullopt;
        }
    } else {
        // Each insecure endpoint must use the exact loopback literal.
        if (apiInsecure && !is_loopback_literal(api.host)) {
            return std::nullopt;
        }
        if (gameInsecure && !is_loopback_literal(game.host)) {
            return std::nullopt;
        }
    }

    return ConnectionPlan{api, game};
}

inline bool has_safe_host_text(const std::string& host) {
    if (host.empty() || host.size() > 253) {
        return false;
    }
    for (char ch : host) {
        const unsigned char byte = static_cast<unsigned char>(ch);
        if (byte <= 32 || byte >= 127) {
            return false;
        }
        switch (ch) {
            case '/':
            case '@':
            case '?':
            case '#':
            case '%':
            case '\\':
                return false;
            default:
                break;
        }
    }
    return true;
}

inline bool matches_host(X509* certificate, const std::string& host) {
    if (!certificate || host.empty() || host.find('\0') != std::string::npos) return false;
    std::unique_ptr<ASN1_OCTET_STRING, decltype(&ASN1_OCTET_STRING_free)> address(
        a2i_IPADDRESS(host.c_str()), ASN1_OCTET_STRING_free);
    if (address) {
        return X509_check_ip(certificate, ASN1_STRING_get0_data(address.get()),
                             static_cast<std::size_t>(ASN1_STRING_length(address.get())), 0) == 1;
    }
    return X509_check_host(certificate, host.data(), host.size(),
        X509_CHECK_FLAG_NEVER_CHECK_SUBJECT | X509_CHECK_FLAG_NO_PARTIAL_WILDCARDS,
        nullptr) == 1;
}

inline bool verified_peer(SSL* ssl, const std::string& host) {
    if (!ssl || SSL_get_verify_result(ssl) != X509_V_OK) return false;
#if OPENSSL_VERSION_NUMBER >= 0x30000000L
    X509* raw = SSL_get1_peer_certificate(ssl);
#else
    X509* raw = SSL_get_peer_certificate(ssl);
#endif
    std::unique_ptr<X509, decltype(&X509_free)> certificate(raw, X509_free);
    return matches_host(certificate.get(), host);
}

const auto& endpoint = plan->api;
httplib::SSLClient api(endpoint.host, endpoint.port);
api.enable_server_certificate_verification(true);
api.set_server_certificate_verifier([host = endpoint.host](SSL* ssl) {
    return tls_identity::verified_peer(ssl, host);
});
if (std::string(argv[3]) != "-") api.set_ca_cert_path(argv[3]);
api.set_follow_location(false);
api.set_connection_timeout(1, 0);
api.set_read_timeout(1, 0);
api.set_write_timeout(1, 0);
const auto result = api.Get("/healthz");
if (!result) { std::puts("TLS or transport failed"); return 4; }
if (result->status != 200 || result->body != "study-meta-ready") {
    std::puts("HTTP response rejected"); return 5;
}
std::puts("HTTPS: trusted peer, expected identity, valid response");
